"use strict";

let appIdController = ($scope, appIdRepository, $appLoader, $q, $dialogs) => {
	$scope.$parent.page = {
		title: language.Generic.ServAdmin.kServerTrustedCodes,
		parent: {
			title: language.Generic.MenuFolders.kFNAppSettings,
			href: `/asp/administration/options.asp`
		},
		back: { history: true },
		leaveConfirmFunc: null,
	};
	
	$scope.$parent.page.leaveConfirmFunc = (leave)	=> {
		if(!$scope.appIds || $scope.appIds.filter($scope.filterChanged).length == 0)
			return leave();
				
		$dialogs.confirm(language.Generic.Common.kConfirmNoSave2).then(leave);
	}

	angular.extend($scope,
        {
            language : language,
            state: {
                dataReady: false,
                dataEmpty: true
			},
			systemAppId: null,
			paging:{
				page: 1,
				size: 50,
				limits:{
					min: 1,
					//max: Infinity
					max: 500,
					step: 5,
					ngStep: 1
				}
			}
        });
	
	let saveDefaultData = (data) => {
		$scope.defaults = $scope.defaults || [];
		data.map((item) => $scope.defaults[item.schoolId] = item.applicationKey);
		return data;
	}

	let updateIds = (data) => {
		let dict = {};
		data.map((o) => dict[o.schoolId] = o);
		angular.forEach($scope.appIds, value => {
			let schoolId = value.schoolId;
			if(dict.hasOwnProperty(schoolId)){
				value.id = dict[schoolId].id;
				value.applicationKey = dict[schoolId].applicationKey;
			} 				
		})
		return data;
	}

	$scope.filterChanged = (item) => $scope.defaults[item.schoolId] !== item.applicationKey;
	
	$scope.Reset = () => {
		let items = $scope.appIds.filter($scope.filterChanged);
		angular.forEach(items, (item) => item.applicationKey = $scope.defaults[item.schoolId] );
		$scope.selectedItem = nullж
	}

	$scope.Save = (item) => {
		appIdRepository.save(item)
			.then(saveDefaultData)
			.then(updateIds)
			.then((result) => console.log(result))
		;
	}

	$scope.SaveAll = () => {
		let items = $scope.appIds.filter($scope.filterChanged);
		appIdRepository.saveAll(items)
			.then(saveDefaultData)
			.then(updateIds)
			.then((result) => console.log(result))
			.then(() => $scope.selectedItem = null)	
		;
	}

	$scope.Select = (item, close) => {
		if(!item || (close && $scope.selectedItem === item)){
			$scope.selectedItem = null;
		}else{
			$scope.selectedItem = item;
		}		
	}

	let mainRequest = appIdRepository.get()
	.then((data) => {
		const compare = (a, b) => a.localeCompare(b);
		const mapedCompare = (map) => (a, b) => compare(map(a),map(b));
		return data
			.sort(mapedCompare(x => x.schoolName))
			.sort(mapedCompare(x => x.address));
	})
	.then((data) => {
		$scope.appIds = data;
		$scope.state.dataEmpty = !data || !data.length;	
		return data;
	})
	.then(saveDefaultData);
	
	let keyRequest = appIdRepository.getSystemKey().then((data) => {
		console.log("key:", data);

		$scope.systemAppId = data;
	})

	$q.all([mainRequest, keyRequest])
		.then(() => {
			$scope.state.dataReady = true;
			$appLoader.hide();
		})
}

angular
	.module("irtech.netcity.admin.appid")
	.controller("appIdController", appIdController)
;


