"use strict";

class BaseRepository {
	constructor($http, $dialogs, $alerts) {
		this.$http = $http;
		this.$dialogs = $dialogs;
		this.$alerts = $alerts;
	}

	handleError(response) {
		alert(response.data.message || response.data.details);
		return response;
	}

	handleResponse(response) {
		return response.data;
	}
}

class AppIdRepository extends BaseRepository {
	get() {
		return this.$http.get("/webapi/applicationsIds")
			.then(this.handleResponse, this.handleError)
	}

	getSystemKey() {
		return this.$http.get("/webapi/systemkey")
			.then(this.handleResponse, this.handleError);
	}

	save(item){
		return this.$http.put("/webapi/applicationsIds", [item])
			.then(this.handleResponse, this.handleError)
	}

	saveAll(items){
		return this.$http.put("/webapi/applicationsIds", items)
			.then(this.handleResponse, this.handleError)
	}
}

angular
	.module("irtech.netcity.admin.appid")
	.factory("appIdRepository", ($http, $dialogs, $alerts) => new AppIdRepository($http, $dialogs, $alerts))
;


